module `IP_MODULE_NAME(lppdr4_init) (
    input   io_peripheralClk,
    input   io_peripheralReset,
    input   io_gpio_sw_n,
    output reg flag_ok,
    input   cfg_done,
    output  cfg_start,
    output  cfg_sel,
    output  cfg_reset
);

localparam [1:0]    IDLE        = 2'b00,
                    CFG_START   = 2'b01,
                    CFG_DONE    = 2'b11;

reg [1:0]           cfg_st,
                    cfg_next;
reg [7:0]           cfg_count;
wire                cfg_ok;
reg [1:0]           buf_reset;
wire                dmReset;

always@(posedge io_peripheralClk)
begin
        buf_reset[1] <= io_peripheralReset;
        buf_reset[0] <= buf_reset[1];
end

assign dmReset = (~buf_reset[0] & buf_reset[1]);

always@(posedge io_peripheralClk or negedge io_gpio_sw_n)
begin
    if(!io_gpio_sw_n)
        flag_ok <= 1'b0;
    else
    begin
        if(cfg_st == CFG_DONE)
            flag_ok <= 1'b1;
        else
            flag_ok <= flag_ok;
    end
end

always@(posedge io_peripheralClk or negedge io_gpio_sw_n)
begin
    if(!io_gpio_sw_n || dmReset)
        cfg_st <= IDLE;
    else
        cfg_st <= cfg_next;
end

always@(*)
begin
    cfg_next = cfg_st;
    case(cfg_st)
    IDLE:
    begin
        if(cfg_count == 'hff)
            cfg_next = CFG_START;
        else
            cfg_next = IDLE;
    end
    CFG_START:
    begin
        if(cfg_done)
            cfg_next = CFG_DONE;
        else
            cfg_next = CFG_START;
    end
    CFG_DONE:
        cfg_next = CFG_DONE;
    default:
        cfg_next = IDLE;
    endcase
end

assign cfg_start    = (cfg_st != IDLE);
assign cfg_ok       = (cfg_st == CFG_DONE);
assign cfg_reset    = (cfg_st == IDLE);
assign cfg_sel      = 1'b0;

always@(posedge io_peripheralClk)
begin
    if(cfg_st == IDLE)
        cfg_count <= cfg_count + 1'b1;
    else
        cfg_count <= 'h0;
end

endmodule


